-- ── SEASON TRANSLATIONS (es) ──
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'season', 's-genesis', 'es', 'name', 'Génesis');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'season', 's-genesis', 'es', 'description', 'Donde todo comenzó. Creación, los primeros humanos, diluvios épicos y drama familiar que pone en vergüenza a la televisión.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'season', 's-exodus', 'es', 'name', 'Éxodo');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'season', 's-exodus', 'es', 'description', 'Esclavitud, plagas, un mar que se parte en dos y supervivencia en el desierto. La película de acción original.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'season', 's-leviticus', 'es', 'name', 'Levítico');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'season', 's-leviticus', 'es', 'description', 'Reglas, rituales y lo que significa ser santo. Menos emocionante que Éxodo, pero la base de todo.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'season', 's-numbers', 'es', 'name', 'Números');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'season', 's-numbers', 'es', 'description', '40 años vagando, quejándose y aprendiendo a confiar en Dios. El viaje por carretera que salió terriblemente mal.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'season', 's-deuteronomy', 'es', 'name', 'Deuteronomio');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'season', 's-deuteronomy', 'es', 'description', 'Los discursos de despedida de Moisés. Un recordatorio de todo lo que Dios hizo y todo lo que Israel debe hacer.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'season', 's-joshua', 'es', 'name', 'Josué');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'season', 's-joshua', 'es', 'description', 'La conquista de la Tierra Prometida. Murallas caen, ciudades arden e Israel por fin llega a casa.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'season', 's-judges', 'es', 'name', 'Jueces');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'season', 's-judges', 'es', 'description', 'La era más oscura de Israel. Héroes surgen, el caos reina y todos hacen lo que quieren.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'season', 's-ruth', 'es', 'name', 'Rut');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'season', 's-ruth', 'es', 'description', 'Una historia de amor de lealtad y redención ambientada en el período más oscuro de la historia de Israel.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'season', 's-1samuel', 'es', 'name', '1 Samuel');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'season', 's-1samuel', 'es', 'description', 'Del último juez al primer rey. Samuel, Saúl y el ascenso de David.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'season', 's-2samuel', 'es', 'name', '2 Samuel');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'season', 's-2samuel', 'es', 'description', 'El reinado de David — triunfos, tragedias y la familia más complicada de la Biblia.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'season', 's-1kings', 'es', 'name', '1 Reyes');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'season', 's-1kings', 'es', 'description', 'La gloria de Salomón, el reino se divide y Elías se enfrenta a 450 profetas.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'season', 's-2kings', 'es', 'name', '2 Reyes');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'season', 's-2kings', 'es', 'description', 'El largo declive. Reyes buenos, reyes malos y la caída de dos naciones.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'season', 's-2chronicles', 'es', 'name', '2 Crónicas');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'season', 's-2chronicles', 'es', 'description', 'La historia del reino del sur contada de nuevo — reformadores, rebeldes y el camino al exilio.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'season', 's-daniel', 'es', 'name', 'Daniel');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'season', 's-daniel', 'es', 'description', 'Fosos de leones, hornos de fuego y visiones apocalípticas. Fidelidad bajo presión.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'season', 's-esther', 'es', 'name', 'Ester');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'season', 's-esther', 'es', 'description', 'Una reina de belleza salva a su pueblo. El nombre de Dios nunca se menciona, pero sus huellas están en todas partes.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'season', 's-jonah', 'es', 'name', 'Jonás');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'season', 's-jonah', 'es', 'description', 'Un profeta huye de Dios, es tragado por un pez y aprende sobre la misericordia por las malas.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'season', 's-matthew', 'es', 'name', 'Mateo');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'season', 's-matthew', 'es', 'description', 'El Evangelio escrito para lectores judíos. Jesús como el Mesías prometido, desde el nacimiento hasta la resurrección.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'season', 's-mark', 'es', 'name', 'Marcos');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'season', 's-mark', 'es', 'description', 'El Evangelio de ritmo rápido. Milagros llenos de acción y el siervo sufriente.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'season', 's-luke', 'es', 'name', 'Lucas');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'season', 's-luke', 'es', 'description', 'El Evangelio más detallado. Jesús como amigo de los marginados, pecadores y olvidados.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'season', 's-john', 'es', 'name', 'Juan');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'season', 's-john', 'es', 'description', 'El Evangelio espiritual. Conversaciones profundas, señales y el Verbo hecho carne.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'season', 's-acts', 'es', 'name', 'Hechos');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'season', 's-acts', 'es', 'description', 'La iglesia primitiva explota. De una habitación en Jerusalén a los confines del Imperio Romano.');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'season', 's-james', 'es', 'name', 'Santiago');
INSERT OR REPLACE INTO content_translations (app_id, entity_type, entity_id, locale, field, value) VALUES ('bible-tea', 'season', 's-james', 'es', 'description', 'La fe sin obras está muerta. Sabiduría práctica para la vida cristiana real.');
